/// <summary>
/// Provides an extension point for validating tutorial inbound transport parameters.
/// </summary>
class OMGTutorialInboundValidator
{
    OMGTutorialInboundDataContract      dataContract;
}

Method.Source:
public OMGTutorialInboundDataContract parmDataContract(OMGTutorialInboundDataContract _dataContract = dataContract)
{
    dataContract = _dataContract;
    return dataContract;
}

/// <summary>
/// Creates the validator selected by the inbound data contract.
/// </summary>
/// <param name = "_dataContract">The parameters to validate.</param>
/// <returns>The validator initialized with the data contract.</returns>
public static OMGTutorialInboundValidator newValidation(OMGTutorialInboundDataContract    _dataContract)
{
    SysDictClass                    sysDictValidationClass = new SysDictClass(_dataContract.validationClassId());
    OMGTutorialInboundValidator     inboundValidator;

    if (sysDictValidationClass)
    {
        inboundValidator = sysDictValidationClass.makeObject();
        inboundValidator.parmDataContract(_dataContract);
    }

    return inboundValidator;
}

/// <summary>
/// Accepts the tutorial parameters until transport-specific checks are implemented.
/// </summary>
/// <returns>True; add parameter checks when implementing a transport.</returns>
